namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 100;
    private static readonly string[] Templates =
    [
        "Deployment to production completed successfully.",
        "New comment on pull request #42.",
        "Build failed for branch 'feature/login'.",
        "User 'admin' updated team permissions.",
        "Disk usage exceeded 90% on server-3.",
        "Scheduled maintenance window starts in 1 hour.",
        "New sign-up from enterprise customer.",
    ];

    /// <summary>Returns the initial batch of notifications (called once during SSR).</summary>
    public Task<List<Notification>> GetInitialNotificationsAsync()
    {
        var now = DateTime.UtcNow;
        var initial = new List<Notification>
        {
            new() { Id = 1, Message = "Welcome! Your account has been created.",        Timestamp = now.AddMinutes(-30) },
            new() { Id = 2, Message = "System update completed — version 2.4.1.",       Timestamp = now.AddMinutes(-18) },
            new() { Id = 3, Message = "Your weekly usage report is ready.",              Timestamp = now.AddMinutes(-5)  },
        };
        return Task.FromResult(initial);
    }

    /// <summary>Simulates checking for new notifications. Returns 0-1 new items per call.</summary>
    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        var results = new List<Notification>();

        // ~40 % chance a new notification arrives each poll cycle
        if (Random.Shared.Next(100) < 40)
        {
            results.Add(new Notification
            {
                Id = Interlocked.Increment(ref _nextId),
                Message = Templates[Random.Shared.Next(Templates.Length)],
                Timestamp = DateTime.UtcNow,
            });
        }

        return Task.FromResult(results);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

using BlazorApp.Services;
using Microsoft.AspNetCore.Components;

namespace BlazorApp.Components.Pages;

public partial class Notifications : IDisposable
{
    [Inject] private NotificationService NotificationSvc { get; set; } = default!;
    [Inject] private PersistentComponentState PersistentState { get; set; } = default!;

    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;
    private bool _pollingStarted;

    protected override async Task OnInitializedAsync()
    {
        // Try to restore notifications that were persisted during SSR.
        // This avoids a second fetch when the circuit becomes interactive.
        _persistSub = PersistentState.RegisterOnPersisting(PersistState);

        if (PersistentState.TryTakeFromJson<List<Notification>>(
                nameof(_notifications), out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            // First render (SSR) — load from the service.
            _notifications = await NotificationSvc.GetInitialNotificationsAsync();
        }
    }

    private Task PersistState()
    {
        PersistentState.PersistAsJson(nameof(_notifications), _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during static SSR, so this
        // guarantees polling only starts once the page is interactive.
        if (firstRender && !_pollingStarted)
        {
            _pollingStarted = true;
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newer = await NotificationSvc.CheckForNewNotificationsAsync();

                if (newer.Count > 0)
                {
                    // Prepend new notifications so the latest appear first.
                    _notifications.InsertRange(0, newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                // Expected on dispose — exit cleanly.
                break;
            }
        }
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

